package app

import (
	"sync"

	"fyne.io/fyne/v2"
)

var (
	metadata     fyne.AppMetadata
	metadataLock sync.RWMutex
)

func init() {
	// Set default metadata
	metadata = fyne.AppMetadata{
		ID:      "com.example",
		Name:    "Fyne App",
		Version: "1.0.0",
		Build:   1,
	}
}

// SetMetadata overrides the application metadata at runtime.
//
// Since: 2.2
func SetMetadata(m fyne.AppMetadata) {
	metadataLock.Lock()
	defer metadataLock.Unlock()
	metadata = m
}

func getMetadata() fyne.AppMetadata {
	metadataLock.RLock()
	defer metadataLock.RUnlock()
	return metadata
}

