package theme

import (
	"encoding/json"
	"errors"
	"fmt"
	"image/color"
	"io"
	"strconv"
	"strings"

	"fyne.io/fyne/v2"
	"fyne.io/fyne/v2/storage"
)

// FromJSON parses a JSON string and returns a Theme.
// On parse error, returns the default theme along with the error.
//
// Since: 2.2
func FromJSON(data string) (fyne.Theme, error) {
	return FromJSONReader(strings.NewReader(data))
}

// FromJSONReader parses JSON from an io.Reader and returns a Theme.
// On parse error, returns the default theme along with the error.
//
// Since: 2.2
func FromJSONReader(r io.Reader) (fyne.Theme, error) {
	var spec jsonThemeSpec
	decoder := json.NewDecoder(r)
	if err := decoder.Decode(&spec); err != nil {
		return Default(), err
	}

	theme := &jsonTheme{
		colors:      make(map[string]color.Color),
		colorsDark:  make(map[string]color.Color),
		colorsLight: make(map[string]color.Color),
		sizes:       make(map[string]float32),
		fonts:       make(map[string]fyne.Resource),
		icons:       make(map[string]fyne.Resource),
	}

	// Parse generic colors
	for name, hexStr := range spec.Colors {
		col, err := parseHexColor(hexStr)
		if err != nil {
			fyne.LogError(fmt.Sprintf("Invalid color hex for %s: %s", name, hexStr), err)
			continue
		}
		theme.colors[name] = col
	}

	// Parse dark variant colors
	for name, hexStr := range spec.ColorsDark {
		col, err := parseHexColor(hexStr)
		if err != nil {
			fyne.LogError(fmt.Sprintf("Invalid color hex for dark.%s: %s", name, hexStr), err)
			continue
		}
		theme.colorsDark[name] = col
	}

	// Parse light variant colors
	for name, hexStr := range spec.ColorsLight {
		col, err := parseHexColor(hexStr)
		if err != nil {
			fyne.LogError(fmt.Sprintf("Invalid color hex for light.%s: %s", name, hexStr), err)
			continue
		}
		theme.colorsLight[name] = col
	}

	// Parse sizes
	for name, value := range spec.Sizes {
		theme.sizes[name] = value
	}

	// Parse fonts
	for style, uri := range spec.Fonts {
		res, err := loadResourceFromURI(uri)
		if err != nil {
			fyne.LogError(fmt.Sprintf("Failed to load font %s from %s", style, uri), err)
			continue
		}
		theme.fonts[style] = res
	}

	// Parse icons
	for name, uri := range spec.Icons {
		res, err := loadResourceFromURI(uri)
		if err != nil {
			fyne.LogError(fmt.Sprintf("Failed to load icon %s from %s", name, uri), err)
			continue
		}
		theme.icons[name] = res
	}

	return theme, nil
}

type jsonThemeSpec struct {
	Colors      map[string]string  `json:"Colors"`
	ColorsDark  map[string]string  `json:"Colors-dark"`
	ColorsLight map[string]string  `json:"Colors-light"`
	Sizes       map[string]float32 `json:"Sizes"`
	Fonts       map[string]string  `json:"Fonts"`
	Icons       map[string]string  `json:"Icons"`
}

type jsonTheme struct {
	colors      map[string]color.Color
	colorsDark  map[string]color.Color
	colorsLight map[string]color.Color
	sizes       map[string]float32
	fonts       map[string]fyne.Resource
	icons       map[string]fyne.Resource
}

func (t *jsonTheme) Color(name fyne.ThemeColorName, variant fyne.ThemeVariant) color.Color {
	nameStr := string(name)

	// Check variant-specific colors first
	if variant == fyne.VariantDark {
		if col, ok := t.colorsDark[nameStr]; ok {
			return col
		}
	} else if variant == fyne.VariantLight {
		if col, ok := t.colorsLight[nameStr]; ok {
			return col
		}
	}

	// Check generic colors
	if col, ok := t.colors[nameStr]; ok {
		return col
	}

	// Fallback to default theme
	return Default().Color(name, variant)
}

func (t *jsonTheme) Font(style fyne.TextStyle) fyne.Resource {
	var key string
	if style.Monospace {
		key = "monospace"
	} else if style.Bold && style.Italic {
		key = "boldItalic"
	} else if style.Bold {
		key = "bold"
	} else if style.Italic {
		key = "italic"
	} else {
		key = "regular"
	}

	if font, ok := t.fonts[key]; ok {
		return font
	}

	// Fallback to default theme
	return Default().Font(style)
}

func (t *jsonTheme) Icon(name fyne.ThemeIconName) fyne.Resource {
	if icon, ok := t.icons[string(name)]; ok {
		return icon
	}

	// Fallback to default theme
	return Default().Icon(name)
}

func (t *jsonTheme) Size(name fyne.ThemeSizeName) float32 {
	if size, ok := t.sizes[string(name)]; ok {
		return size
	}

	// Fallback to default theme
	return Default().Size(name)
}

// parseHexColor parses a hex color string and returns a color.Color.
// Supports formats: #rgb, #rgba, #rrggbb, #rrggbbaa (with or without #)
func parseHexColor(hex string) (color.Color, error) {
	// Remove # prefix if present
	hex = strings.TrimPrefix(hex, "#")

	var r, g, b, a uint8
	a = 0xff // default alpha

	switch len(hex) {
	case 3: // rgb
		vals, err := parseHexDigits(hex, 1)
		if err != nil {
			return color.Transparent, err
		}
		r = vals[0] | (vals[0] << 4)
		g = vals[1] | (vals[1] << 4)
		b = vals[2] | (vals[2] << 4)

	case 4: // rgba
		vals, err := parseHexDigits(hex, 1)
		if err != nil {
			return color.Transparent, err
		}
		r = vals[0] | (vals[0] << 4)
		g = vals[1] | (vals[1] << 4)
		b = vals[2] | (vals[2] << 4)
		a = vals[3] | (vals[3] << 4)

	case 6: // rrggbb
		vals, err := parseHexDigits(hex, 2)
		if err != nil {
			return color.Transparent, err
		}
		r = vals[0]
		g = vals[1]
		b = vals[2]

	case 8: // rrggbbaa
		vals, err := parseHexDigits(hex, 2)
		if err != nil {
			return color.Transparent, err
		}
		r = vals[0]
		g = vals[1]
		b = vals[2]
		a = vals[3]

	default:
		return color.Transparent, errors.New("invalid hex color format")
	}

	return color.NRGBA{R: r, G: g, B: b, A: a}, nil
}

func parseHexDigits(hex string, digitsPer int) ([]uint8, error) {
	count := len(hex) / digitsPer
	result := make([]uint8, count)

	for i := 0; i < count; i++ {
		start := i * digitsPer
		end := start + digitsPer
		val, err := strconv.ParseUint(hex[start:end], 16, 8)
		if err != nil {
			return nil, err
		}
		result[i] = uint8(val)
	}

	return result, nil
}

func loadResourceFromURI(uri string) (fyne.Resource, error) {
	parsed, err := storage.ParseURI(uri)
	if err != nil {
		return nil, err
	}

	return fyne.LoadResourceFromURI(parsed)
}

