package binding

import (
	"fmt"

	"fyne.io/fyne/v2"
	"fyne.io/fyne/v2/storage"
)

// NewSprintf creates a formatted string binding that combines multiple data bindings.
// When any source binding changes, the formatted string is automatically updated.
// Set() parses the string back using fmt.Sscanf and updates each source binding.
//
// Since: 2.2
func NewSprintf(format string, bindings ...DataItem) String {
	s := &sprintfBinding{
		format:   format,
		bindings: bindings,
	}

	// Listen to all source bindings
	for _, b := range bindings {
		b.AddListener(s)
	}

	return s
}

// StringToStringWithFormat wraps a String binding with a format string.
// If format is "%s", returns the original binding directly.
//
// Since: 2.2
func StringToStringWithFormat(str String, format string) String {
	if format == "%s" {
		return str
	}
	return NewSprintf(format, str)
}

type sprintfBinding struct {
	base
	format   string
	bindings []DataItem
	lastErr  error
}

func (s *sprintfBinding) Get() (string, error) {
	if s.lastErr != nil {
		return "", s.lastErr
	}

	values := make([]interface{}, len(s.bindings))
	for i, b := range s.bindings {
		val, err := s.getValue(b)
		if err != nil {
			return "", err
		}
		values[i] = val
	}

	return fmt.Sprintf(s.format, values...), nil
}

func (s *sprintfBinding) Set(str string) error {
	// Prepare pointers for Sscanf
	values := make([]interface{}, len(s.bindings))
	for i, b := range s.bindings {
		values[i] = s.getPointerForType(b)
	}

	// Parse the string
	n, err := fmt.Sscanf(str, s.format, values...)
	if err != nil {
		return err
	}
	if n != len(s.bindings) {
		return fmt.Errorf("expected %d values, got %d", len(s.bindings), n)
	}

	// Set each binding with the parsed value
	for i, b := range s.bindings {
		if err := s.setValue(b, values[i]); err != nil {
			return err
		}
	}

	return nil
}

func (s *sprintfBinding) DataChanged() {
	s.lastErr = nil
	for _, b := range s.bindings {
		if _, err := s.getValue(b); err != nil {
			s.lastErr = err
			break
		}
	}
	s.trigger()
}

func (s *sprintfBinding) getValue(item DataItem) (interface{}, error) {
	switch v := item.(type) {
	case Bool:
		return v.Get()
	case Float:
		return v.Get()
	case Int:
		return v.Get()
	case Rune:
		return v.Get()
	case String:
		return v.Get()
	case Bytes:
		return v.Get()
	case URI:
		u, err := v.Get()
		if err != nil {
			return nil, err
		}
		if u == nil {
			return "", nil
		}
		return u.String(), nil
	default:
		return nil, fmt.Errorf("unsupported binding type: %T", item)
	}
}

func (s *sprintfBinding) getPointerForType(item DataItem) interface{} {
	switch item.(type) {
	case Bool:
		var v bool
		return &v
	case Float:
		var v float64
		return &v
	case Int:
		var v int
		return &v
	case Rune:
		var v rune
		return &v
	case String:
		var v string
		return &v
	case URI:
		var v string
		return &v
	default:
		var v interface{}
		return &v
	}
}

func (s *sprintfBinding) setValue(item DataItem, ptr interface{}) error {
	switch v := item.(type) {
	case Bool:
		return v.Set(*ptr.(*bool))
	case Float:
		return v.Set(*ptr.(*float64))
	case Int:
		return v.Set(*ptr.(*int))
	case Rune:
		return v.Set(*ptr.(*rune))
	case String:
		return v.Set(*ptr.(*string))
	case Bytes:
		// Bytes cannot be round-tripped
		return fmt.Errorf("bytes binding cannot be set via formatted string")
	case URI:
		str := *ptr.(*string)
		u, err := storage.ParseURI(str)
		if err != nil {
			return err
		}
		return v.Set(u)
	default:
		return fmt.Errorf("unsupported binding type for set: %T", item)
	}
}

