// NewAllStrings creates a validator that checks if input matches any string in the provided list.
// Returns an error if the string is not in the allowed list.
//
// Since: 2.2
func NewAllStrings(valid []string) fyne.StringValidator {
	return func(text string) error {
		for _, v := range valid {
			if text == v {
				return nil
			}
		}
		return errors.New("value not in allowed list")
	}
}

